const jobs = {
    T19: { duration: 3, resources: ['R0', 'R1'], predecessors: [] },
    T47: { duration: 5, resources: ['R0'], predecessors: [], deadline: 10 },
    T45: { duration: 1, resources: ['R0'], predecessors: [], deadline: 11 },
};

const horario = generateHorario(jobs);
console.log(horario);
```

