Para crear un horario factible con las especificaciones dadas, primero debemos definir una estructura para representar los tareas y sus recursos. Luego podemos utilizar algoritmos de flujo dinámico para ordenarlas en función de sus dependencias y duración.

```javascript
const taskResources = {
  T32: ["R1"],
  T78: ["R0"],
  T34: ["R0", "R1"]
};

const resourceAssignments = {};

function assignResources(tarefas, recursos) {
  tareas.forEach((tarefa) => {
    if (resourceAssignments[tarefa.id]) return;
    let recursosRestantes = [...recursos];
    resourcesRestantes.forEach((r) => {
      if (!taskResources[tarefa.id].includes(r)) {
        resourceAssignments[tarefa.id] = r;
        return;
      }
    });
  });
}

function calculateDeadlines(tareas) {
  const deadlines = {};

  tareas.forEach((tarea) => {
    deadlines[tarea.id] = tarea.deadline;
  });

  return deadlines;
}

function createHorario(tareas, deadlines) {
  let horario = [];

  // Selecciona una tarea para comenzar primero
  const tareaSelectada = Object.keys(deadlines).sort((a, b) => deadlines[a] - deadlines[b])[0];
  const recursosSelectados = taskResources[tareaSelectada];

  while (recursosSelectados.length > 0) {
    // Busca la tarea con el recurso más atractivo
    let mejorTarea;
    let maxDuracion = 0;

    Object.keys(resourceAssignments).forEach((id) => {
      if (!recursosSelectados.includes(id)) return;
      const duracion = deadlines[id] - horario[horario.length - 1].start;
      if (duracion > maxDuracion) {
        mejorTarea = id;
        maxDuracion = duracion;
      }
    });

    // Asigna el recurso al nuevo tarea
    horario.push({ start: horario[horario.length - 1].end, resource: mejorTarea });
    recursosSelectados.splice(recursosSelectados.indexOf(mejorTarea), 1);
    const deadline = deadlines[mejorTarea] - maxDuracion;
    horario.push({ start: horario[horario.length - 1].start + maxDuracion, resource: melhorTarea });
    deadlines[mejorTarea] -= maxDuracion;

    // Repite el proceso para la próxima tarea
    const recursosNuevos = Object.keys(resourceAssignments).filter((id) => !recursosSelectados.includes(id));
    assignResources(tareas, recursosNuevos);
  }

  return horario;
}

const tareas = [
  {"id": "T32", "duration": 2, "resources": ["R1"], "predecessors": [], "deadline": 5},
  {"id": "T78", "duration": 2, "resources": ["R0"], "predecessors": [], "deadline": 3},
  {"id": "T34", "duration": 1, "resources": ["R0", "R1"], "predecessors": ["T32"], "deadline": 7}
];

const deadlines = calculateDeadlines(tareas);
const horario = createHorario(tareas, deadlines);

console.log(horario);
```

