Aquí te muestro el código en JavaScript que podría cumplir con las especificaciones:

```javascript
function generarHorario(jobs) {
    const horario = [];

    // Ordenar las tareas según sus duraciones y deadlines
    jobs.sort((a, b) => a.duration - b.duration || a.deadline - b.deadline);

    for (const job of jobs) {
        // Crear un elemento JSON para cada tarea
        const tarea = { id: job.id, start: 0, resource: '' };

        while (job.resources.length > 0 && job.deadline <= task.start) {
            // Buscar la tarea más reciente que no haya terminado y puede completarse antes de que termine la tarea actual
            let encontrado = false;
            for (const task of horario) {
                if (task.id === task.start) {
                    encontrado = true;
                    break;
                }
            }

            // Si se encontró una tarea que no ha terminado, asignarla a la tarea actual
            if (encontrado) {
                tarea.resource = jobs.find(j => j.id === task.id).resources[0];
                break;
            } else {
                // Si no se encontró ninguna tarea que no haya terminado y puede completarse antes de que termine la tarea actual, agregarla al horario
                if (job.duration + job.deadline <= task.start) {
                    task.start = job.duration + job.deadline;
                    for (const resource of job.resources) {
                        const index = horario.findIndex(t => t.id === task.start);
                        if (index !== -1) {
                            horario[index].start += job.duration;
                        } else {
                            horario.push({ id: task.start, start: 0, resource });
                        }
                    }
                }
            }

            // Agregar la tarea al horario
            horario.push(tarea);
        }
    }

    return horario;
}

const jobs = [
    {"id": "T44", "duration": 3, "resources": ["R0", "R1"], "predecessors": [], "deadline": 11},
    {"id": "T98", "duration": 3, "resources": ["R1"], "predecessors": [], "deadline": 10},
    {"id": "T66", "duration": 2, "resources": ["R0", "R1"], "predecessors": [], "deadline": 4}
];

const horario = generarHorario(jobs);
