Para crear un horario factible con los datos proporcionados, necesitaremos utilizar algoritmos de planificación de tareas. Un ejemplo sencillo podría ser el siguiente:

```javascript
const data = {
    "jobs": [
        {"id": "T44", "duration": 3, "resources": ["R0", "R1"], "predecessors": [], "deadline": 11},
        {"id": "T98", "duration": 3, "resources": ["R1"], "predecessors": [], "deadline": 10},
        {"id": "T66", "duration": 2, "resources": ["R0", "R1"], "predecessors": [], "deadline": 4}
    ]
};

const horario = createHorario(data);

console.log(horario);
```

Este código crea una función `createHorario` que recibe el objeto de tareas y returna un objeto JSON con el horario ordenado:

```javascript
function createHorario(tareas) {
    const horario = [];

    while (tareas.jobs.length > 0) {
        let tarea = null;

        for (const tarea of tareas.jobs) {
            if (tarea.predecessors.length === 0 && tarea.deadline <= tareas.jobs.reduce((a, b) => a.deadline < b.deadline ? a : b).deadline) {
                tarea = tarea;
                break;
            }
        }

        if (tarea == null) {
            throw new Error("No se ha encontrado una tarea con no predecesor y deadline no menor que la del siguiente");
        }

        const recursos = tarea.resources.filter(r => r !== 'R0' && r !== 'R1').join(',');

        const start = Math.max(...tareas.jobs.map(t => t.start));
        const finish = start + tarea.duration;

        horario.push({
            "id": tarea.id,
            "start": start,
            "resource": recursos
        });

        for (const task of tareas.jobs) {
            if (task.deadline <= finish && !task.predecessors.includes(tarea.id)) {
                task.predecessors.push(tarea.id);
            }
        }

        tareas.jobs = tareas.jobs.filter(j => j !== tarea);
    }

    return horario;
}
```

Este código crea un horario en el que cada tarea sigue la siguiente orden:

1.  Se busca una tarea con no predecesor y deadline menor que la del siguiente.
2.  Una vez encontrado, se agrega al horario como tarea.
3.  Para las tareas sin predecesores, se agrega su inicio y termino en el mismo orden de los recursos utilizados.
4.  Las tareas con predecesor son agregadas a la lista con el inicio y termino del siguiente.

