### Algoritmo para generar el horario

El algoritmo básico para resolver este tipo de problemas es el algoritmo binario, pero en este caso, podemos aprovechar una técnica más simple basada en iteraciones. Lo siguiente es un ejemplo de cómo implementar el algoritmo para generar el horario:

```javascript
function generateHorario(jobDuration) {
    const job = {
        id: 'T' + (jobDuration - 1),
        start: 0,
        deadline: jobDuration,
        resources: ['R0'],
        predecessors: []
    };

    return [job];
}

// Crear un conjunto de tareas con sus respectivos duraciones y recursos
const jobs = [
    generateHorario(2), // T23
    generateHorario(5), // T65
    generateHorario(7)  // T27
];

function createSchedule(jobs, deadline) {
    const schedule = [];

    for (let i = 0; i < jobs.length - 1; i++) {
        let currentJob = jobs[i];
        let nextJob = jobs[i + 1];

        while (currentJob.deadline > nextJob.deadline && 
               currentJob.start <= nextJob.start) {
            // Añadir la tarea actual a la lista de tareas con su start, deadline y recursos
            schedule.push({
                id: 'T' + (nextJob.id - 1),
                start: Math.max(currentJob.start, nextJob.start), 
                deadline: currentJob.deadline,
                resource: currentJob.resources[0] // La primera resource se utiliza porque tiene la menor duración y es el primer recurso
            });

            // Actualizar las variables para la próxima iteración
            [currentJob.start, currentJob.deadline] = [nextJob.start, nextJob.deadline];
        }
    }

    return schedule;
}

function printSchedule(schedule) {
    const output = JSON.stringify(schedule);
    console.log(output);
}

const deadline = 18; // Define la duración total del día (en minutos)
const schedule = createSchedule(jobs, deadline);

printSchedule(schedule);
```

