const tasks = [];
// Asignar el tiempo total necesario para cada tarea
for (const task of jobs) {
    let totalDuration = 0;
    const resourcesNeeded = [];

    // Sumar el tiempo total necesario para completar la tarea, teniendo en cuenta las duraciones de los recursos y predecesoras
    for (let i = 0; i < task.resources.length; i++) {
        const resource = task.resources[i];
        if (resourcesNeeded[resource]) {
            resourcesNeeded[resource].push(totalDuration);
        } else {
            resourcesNeeded[resource] = [totalDuration];
        }

        // Calcula el tiempo total necesario para completar la tarea
        let timeTakenSoFar = 0;
        for (const predecessor of task.predecessors) {
            if (!resourcesNeeded[predecessor]) {
                break;
            }
            const predecessorTime = resourcesNeeded[predecessor].reduce((sum, time) => sum + time, 0);
            timeTakenSoFar += predecessorTime;
        }

        // Añade la tarea al horario
        tasks.push({ ...task, deadline: Math.max(task.deadline, timeTakenSoFar + totalDuration) });
    }
}
```

