### Algoritmo para generar el horario

1.  Asigna recursos a cada tarea según sea necesario para cumplir con las condiciones de predecesora y sucesor.
2.  Llave del array: `start_time`, que representa cuando se debe comenzar una tarea, y la deadline, que es la fecha límite para completarla.

### Implementación en Python

```python
import heapq
from datetime import datetime, timedelta

# Crear un árbol de precedentes
precedents = {}

def add_predecessor(job_id, predecessor_id):
    if job_id not in precedents:
        precedents[job_id] = []
    if predecessor_id not in precedents[job_id]:
        precedents[job_id].append(predecessor_id)

def get_next_task(predecessors, start_time):
    # Busca el siguiente recurso para cada tarea
    for job_id, predecessors_list in precedents.items():
        for predecessor_id in predecessors_list:
            if predecessor_id not in precedents.get(job_id, []):
                heapq.heappush(predecessor_list, (predecessor_id, 0))

    # Busca el siguiente recurso para cada tarea
    next_tasks = []
    while True:
        current_job_id, deadline_time = heapq.heappop(predecessor_list)

        if deadline_time >= start_time:
            break

        for predecessor in precedents.get(current_job_id, []):
            if predecessor not in next_tasks and (deadline_time + 1) <= start_time:
                heapq.heappush(next_tasks, (predecessor, (deadline_time + 1, current_job_id)))

    # Busca el siguiente recurso para cada tarea
    for task_id, deadline_time in next_tasks:
        if deadline_time >= start_time and job_id not in precedents:
            add_predecessor(job_id, task_id)

    return next_tasks

def generate_horario():
