    jobs = [
        {"id": "T86", "duration": 5, "resources": ["R0"], "predecessors": [], "deadline": 10},
        {"id": "T75", "duration": 5, "resources": ["R0", "R1"], "predecessors": [], "deadline": 15},
        {"id": "T76", "duration": 4, "resources": ["R1"], "predecessors": [], "deadline": 6}
    ]

    start_time = datetime.now()
    horario = []

    # Agregar las tareas con recursos R0
    for job in jobs:
        if job["resource"] == "R0":
            heapq.heappush(horario, (job["duration"], job["id"]))

    # Agregar las tareas con recursos R1
    while True:
        current_job = heapq.heappop(horario)[1]
        deadline_time = start_time + timedelta(minutes=current_job[0])

