tareas = [{'duration': d, 'resources': r} for r in recursos for d in range(0, d+1)] + \
        [{'duration': d, 'resources': r} for r in recursos for d in range(0, d+1), r in ['R0', 'R1']]

# Aplicar algoritmo de Schedulación Lineal para asignar tareas a recursos
G = nx.DiGraph()
for tarea in tareas:
    for predecesor in predecesores:
        G.add_edge(predecesor, tarea['id'], weight=len(G.edges(predecesor, tarea['id'])))
    G.add_edge(tarea['id'], tarea['id'])

posiciones = nx.spring_layout(G)
asignaciones = {}

