    asignaciones[tarea['id']] = {'start': posiciones[tarea['id']], 'resource': G.nodes[tarea['id']]['weight']}
    for predecesor, peso in list(G.edges(tarea['id'], key=lambda x: x[1]['duration'])):
        if tarea['id'] not in [a['id'] for a in asignaciones.values()]:
