Para crear un horario factible con los datos proporcionados, podemos seguir estos pasos:

1. Crear una lista de tareas para cada recurso.
2. Ordenar las tareas según su duración y predecesores.
3. Agregar el estado "terminada" a cada tarea cuando la siguiente tarea que depende de ella termine.

A continuación, se muestra un ejemplo del código en Python:
```python
import json

# Datos proporcionados
jobs = [
    {"id": "T77", "duration": 3, "resources": ["R1"], "predecessors": [], "deadline": 4},
    {"id": "T22", "duration": 5, "resources": ["R0"], "predecessors": ["T77", "T59"], "deadline": 13},
    {"id": "T53", "duration": 5, "resources": ["R0"], "predecessors": ["T87", "T59"], "deadline": 18},
    {"id": "T59", "duration": 1, "resources": ["R0"], "predecessors": ["T87"], "deadline": 8},
    {"id": "T87", "duration": 4, "resources": ["R1"], "predecessors": [], "deadline": 9}
]

# Crea una lista de tareas para cada recurso
tareas = {}
for job in jobs:
    for resource in job["resources"]:
        if resource not in tareas or len(tareas[resource]) + job["duration"] > max([t["duration"] for t in jobs]):
            tareas[resource] = [{"id": f"T{job['id']}_{i}", "start": 0, "resource": resource} for i in range(len(job["duration"]))]

# Ordena las tareas según su duración y predecesores
tareas = sorted(tareas.items(), key=lambda x: (x[1]["duration"], x[1]["predecessors"]), reverse=True)

# Agrega el estado "terminada" a cada tarea cuando la siguiente tarea que depende de ella termine
for i in range(len(tareas)):
    for j in range(i + 1, len(tareas)):
        if set(tareas[j][1]["resources"]) & set(tareas[i][1]["resources"]):
            tareas[j].append({"state": "terminada", "resource": tareas[i][1]["resource"]})

# Crea un horario JSON
horario = [{"id": t["id"], "start": t["start"], "resource": t["resource"]} for t in tareas]

print(json.dumps(horario, indent=4))
```
