```python
import json
from typing import List, Dict

# Datos proporcionados
jobs = {
    "T58": {"duration": 2, "resources": ["R0"], "predecessors": [], "deadline": 3},
    "T49": {"duration": 5, "resources": ["R0", "R1"], "predecessors": ["T15"], "deadline": 16},
