    "T17": {"duration": 4, "resources": ["R0", "R1"], "predecessors": ["T58"], "deadline": 6}
}

# Crear un listado de tareas para cada job
tareas = {}
for job, info in jobs.items():
    tareas[job] = []

    # Ordenar las tareas por deadline y recursos
    for resource in info["resources"]:
        tareas[job].append((info["deadline"], info["duration"], resource))

# Agregar la lista de tareas a una lista de listas
horario = []
for job, tasks in tareas.items():
    horario.append([task[0] for task in tasks])

