function generarHorario(data) {
  const horarioFactico = {};
  data.jobs.forEach(tarea => {
    horarioFactico[tarea.id] = {
      start: 0,
      resource: tarea.resource[0],
      duration: tarea.duration
    }
  });

  // Actualizar el horario con las dependencias
  Object.keys(horarioFactico).forEach(idTarea => {
    const tareaActual = data.jobs.find(t => t.id === idTarea);
    if (tareaActual) {
      let previente = null;
      horarioFactico[idTarea].resource = tareaActual.resources[0];
