```python
from typing import List

class Task:
    def __init__(self, id: str, duration: int, resources: list, predecessor_id: str):
        self.id = id
        self.duration = duration
        self.resources = resources
        self.predecessor_id = predecessor_id

    def start(self):
        return f"{self.id}={0}"

    def end(self):
        return f"{self.id}={1}"


class Resource:
    def __init__(self, id: str, name: str):
        self.id = id
        self.name = name


def create_tasks(tasks):
    tasks_dict = {}

