class Task {
  constructor(id, duration, resources) {
    this.id = id;
    this.duration = duration;
    this.resources = resources;
  }
}

class Resource {
  constructor(id, name) {
    this.id = id;
    this.name = name;
  }
}

class Graph {
  constructor() {
    this.nodes = {};
  }

  addNode(id, node) {
    if (!this.nodes[id]) {
      this.nodes[id] = [];
    }
    this.nodes[id].push(node);
  }

  addEdge(from, to, weight) {
    if (this.nodes[from] && this.nodes[to]) {
      this.nodes[from].push({ id: to, weight });
    }
  }

  getNodes() {
    return Object.values(this.nodes);
  }
}

class Solver {
  constructor(graph) {
    this.graph = graph;
    this.tasks = [];
  }

  addTask(task) {
    this.tasks.push(task);
  }

  solve() {
    // Crea un nuevo gráfico
    const g = new Graph();

    // Agrega todos los recursos disponibles
    for (const resource of g.getNodes()) {
      if (!resource.resources.length) {
        resource.resources.push(new Resource('R0', 'Resursos'));
      }
