        }

        const newNode = new Resource(task.id, 'T' + index);
        g.addNode(newNode.id, newNode);

        // Agrega la tarea a los recursos seleccionados
        for (const r of resource.resources) {
          if (!r.name || !this.graph.getNodes().find(r => r.id === r.name)) {
