          }

          g.addEdge(node.id, newNode.id, task.duration);
        }

        // Elimina los recursos no utilizados
        for (const r of resource.resources) {
          if (!r.name || !this.graph.getNodes().find(r => r.id === r.name)) {
            this.graph.getNodes().delete(r.id);
          }
        }
      }
    });

    return g;
  }

