import json
from typing import List, Dict

def crear_horario_tareas(job_data: List[Dict]) -> List[Dict]:
    # Crear tareas
    tareas = []
    for job in job_data:
        tareas.append({"id": job["id"], "start": 0, "resource": job["resources"]})

    # Buscar la predecesora con mayor prioridad (en este caso, T18)
    max_priority_tarea = None
    max_priority = -1
    for tarea in tareas:
        if not tarea["predecessors"]:
            if max_priority < 0 or tareas.index(tarea) > max_priority:
                max_priority = tareas.index(tarea)
                max_priority_tarea = tarea

    # Asignar la predecesora a la tarea correspondiente
    if max_priority_tarea:
        tareas[max_priority]["predecessors"].append(max_priority_tarea["id"])

    return tareas

# Cargar los datos de job
job_data = {
    "T48": {"duration": 5, "resources": ["R1"], "predecessors": ["T49"], "deadline": 8},
