function getTareaPrioridad(tareas) {
    return tareas.sort((a, b) => a.deadline - b.deadline).reduce((acumulador, tarea) => acumulador + (tarea.duration / 60), 0);
}

function obtenerRecursosDisponibles(tareas, recursosDisponibles) {
    let recursosNecesarios = {};

    for (let tarea in tareas) {
        if (!recursosDisponibles[tarea.resources]) {
            recursosNecesarios[tarea.resources] = 0;
        }

        recursosNecesarios[tarea.resources]++;
    }

    return recursosNecesarios;
}

function calcularHorario(tareas, recursosDisponibles, tareasPrioritarias) {
    let horario = [];

    for (let tarea in tareasPrioritarias) {
        if (tareasPrioritarias[tarea].duration <= 0 || !recursosDisponibles[tareas[tarea].resources]) {
            continue;
        }

        horario.push({
            "id": tarea,
            "start": 0,
            "resource": tareas[tarea].resources
        });
    }

    return horario;
}
