Aquí te presento un ejemplo de cómo podrías implementarlo:

```javascript
// Data
const jobs = {
    T60: { duration: 2, resources: ["R0"], predecessors: ["T48"], deadline: 5 },
    T74: { duration: 4, resources: ["R0", "R2"], predecessors: ["T37"], deadline: 9 },
    T44: { duration: 4, resources: ["R0", "R2"], predecessors: ["T37"], deadline: 5 },
    T45: { duration: 2, resources: ["R1"], predecessors: ["T74"], deadline: 15 },
    T48: { duration: 3, resources: ["R0", "R1", "R2"], predecessors: [], deadline: 3 },
    T37: { duration: 1, resources: ["R1"], predecessors: [], deadline: 1 },
    T76: { duration: 4, resources: ["R0", "R1"], predecessors: ["T74"], deadline: 13 }
};

// Función para generar el horario
function generateHorario(jobs) {
    const graph = {};

    // Crear el gráfico de aristas
    for (const job of jobs) {
        if (!graph[job.id]) {
            graph[job.id] = [];
        }

        for (const predecessor of job.predecessors) {
            if (!graph[predecessor.id]) {
                graph[predecessor.id] = [];
            }

            graph[predecessor.id].push(job.id);
        }
    }

    // Generar el horario
    const queue = Object.keys(jobs).map(id => ({ id, duracion: jobs[id].duration }));

    while (queue.length > 0) {
        const { id, duracion } = queue.shift();

        if (duracion <= 0) {
            continue;
        }

        for (const nextJob of graph[id]) {
            if (nextJob && duracion + jobs[nextJob].duration <= 0) {
                duracion += jobs[nextJob].duration;

                queue.push({ id: nextJob, duracion });
            } else if (!nextJob || duracion < 0) {
                continue;
            }
        }
    }

    // Encontrar el horario
    const horario = {};

    for (const job of jobs) {
        const { start } = generateHorarioFromTask(job);

        horario[job.id] = { start, resource: job.resources[0], id };
    }

    return horario;
}

// Función para generar el horario desde un tarea
function generateHorarioFromTask(job) {
    let tiempoMaximo = 0;

    for (const task of Object.values(jobs)) {
        if (task.duration <= tiempoMaximo && task.deadline > 0) {
            return { start: 0, resource: task.resources[0], id: job.id };
        } else if (tiempoMaximo < 0) {
            tiempoMaximo = 0;
        }
    }

    return null; // No se puede generar el horario para esta tarea
}

// Ejecutar el algoritmo
const horario = generateHorario(jobs);

// Convertir a JSON y escribir en un archivo
const json = JSON.stringify(horario, null, 2);
console.log(json);
```

Este código crea un gráfico de aristas para representar las relaciones entre las tareas. Luego, utiliza un algoritmo dinámico de horizontales para generar un orden en el que se pueden realizar las tareas.

El orden se define mediante la siguiente estrategia:

- Primero, se selecciona una tarea con una duración no negativa y un final mayor o igual a 0.
- A continuación, se busca la tarea más cercana al final de la tarea seleccionada. Esto se hace en el gráfico de aristas para encontrar todas las opciones posibles.
- Para cada opción, se verifica si su finalidad es mayor o igual a 0 y si existe una tarea con una duración menor que 0. Si no hay tales tareas, se considera que no se pueden realizar.
- El proceso se repite hasta que todas las tareas sean completadas.

