Para crear el horario, creamos un grafo donde cada tarea es una vértice y cada relación entre tareas es una arista. En el grafo, las aristas son representadas por `(tarea1,tarea2)` y los nodos son representados por `(tarea1,predecesores(tarea1))`.

A continuación, creamos un algoritmo que recorre el grafo en orden y, para cada tarea, agrega una entrada al horario con la tarea como "start" y su deadline como 0.

```javascript
const DGD = (jobs) => {
  const graph = {};
  const inDegree = {};

  // Inicializamos los nodos del grafo
  for (const job of jobs.jobs) {
    if (!graph[job.id]) {
      graph[job.id] = [];
      inDegree[job.id] = 0;
    }
  }

  // Agregamos las aristas al grafo
  for (const job of jobs.jobs) {
    for (const predecessor of job.predecessors) {
      if (!graph[predecessor]) {
        graph[predecessor] = [];
        inDegree[predecessor] = 0;
      }
      graph[predecessor].push(job.id);
      inDegree[job.id]++;
    }
  }

  // Recorre el grafo y agrega las entradas al horario
  const horario = {};
  for (const job of jobs.jobs) {
    if (inDegree[job.id] === 0) {
      horario[job.id] = { start: 0, deadline: job.deadline };
    }
  }

  return horario;
}

// Ejecución
const horario = DGD(jobs);
console.log(horario);
